from math import cos, sin

theta = 0.5
q, k = (1.0, 0.5), (0.3, 0.8)

def rotate(x, angle):
    return (x[0] * cos(angle) - x[1] * sin(angle), x[0] * sin(angle) + x[1] * cos(angle))

def score(pos_q, pos_k):
    rq, rk = rotate(q, pos_q * theta), rotate(k, pos_k * theta)
    return round(rq[0] * rk[0] + rq[1] * rk[1], 6)

same_gap = {(5, 2): score(5, 2), (12, 9): score(12, 9), (103, 100): score(103, 100)}
other_gap = score(10, 2)
print("gap 3 everywhere:", same_gap)
print("gap 8:", other_gap)
